دالة تكرار_الكلمات(نص) {
    متغير خ = {}
    متغير ق = افصل(نص، " ")
    من_أجل (كلمة في ق) {
        إذا (يحوي(خ، كلمة)) {
            خ[كلمة] = خ[كلمة] + ١
        } وإلا {
            خ[كلمة] = ١
        }
    }
    ارجع خ
}
